#!/usr/bin/env node
/**
 * Generated by governance/portfolio/toolkit. Local only — do not deploy.
 * Starts the UI or API for this application without depending on a global package manager version.
 */
import { spawn } from "node:child_process";
import { createReadStream, existsSync, readFileSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, extname, join, normalize, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const config = JSON.parse(readFileSync(join(here, "local-preview.json"), "utf8"));
const role = process.argv[2] ?? "ui";

function pick(roleName) {
  const candidates = config.commands?.[roleName] ?? [];
  return candidates.find((candidate) => !candidate.check || existsSync(join(root, candidate.check))) ?? null;
}

if (config.staticRoot && role === "ui") {
  serveStatic(join(root, config.staticRoot), config.staticPort ?? 4173);
} else {
  const spec = pick(role);
  if (!spec) {
    console.error(`No local ${role} command is recorded for ${config.name}.`);
    process.exit(2);
  }
  console.log(`${config.name} ${role}: ${spec.command} ${spec.args.join(" ")}`);
  const child = spawn(spec.command, spec.args, {
    cwd: root,
    stdio: "inherit",
    shell: process.platform === "win32" && ["pnpm", "npm", "npx"].includes(spec.command),
    env: { ...process.env, ...(config.env ?? {}) },
  });
  child.on("exit", (code) => process.exit(code ?? 0));
  process.on("SIGINT", () => child.kill("SIGTERM"));
}

function serveStatic(directory, port) {
  const types = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".mjs": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".webp": "image/webp",
    ".ico": "image/x-icon",
    ".woff2": "font/woff2",
  };

  createServer((request, response) => {
    try {
      const url = new URL(request.url ?? "/", "http://127.0.0.1");
      let pathname = decodeURIComponent(url.pathname);
      if (pathname.endsWith("/")) pathname += "index.html";
      const candidate = normalize(join(directory, pathname));
      if (!candidate.startsWith(directory + sep) && candidate !== directory) {
        response.writeHead(403).end("Forbidden");
        return;
      }
      const file = existsSync(candidate) && statSync(candidate).isFile() ? candidate : join(directory, "index.html");
      response.writeHead(200, { "Content-Type": types[extname(file)] ?? "application/octet-stream" });
      createReadStream(file).pipe(response);
    } catch {
      response.writeHead(500).end("Local preview error");
    }
  })
    .listen(port, "127.0.0.1", () => console.log(`${config.name} static preview: http://127.0.0.1:${port}/`));
}
